@font-face { 
	font-family: "noto-serif-kr-medium";
	font-weight: 400;
	font-style: normal;
	src: url(data:application/font-woff;base64,);
}
@font-face { 
	font-family: "noto-serif-kr-black";
	font-weight: 900;
	font-style: normal;
	src: url(data:application/font-woff;base64,);
}
@font-face { 
	font-family: "Pretendard-Regular";
	font-weight: 400;
	font-style: normal;
	src: url(data:application/font-woff;base64,);
}
@font-face { 
	font-family: "Pretendard-Bold";
	font-weight: 700;
	font-style: normal;
	src: url(data:application/font-woff;base64,);
}
@font-face { 
	font-family: "ITC Slimbach Std";
	font-weight: 400;
	font-style: normal;
	src: url(data:application/octet-stream;base64,);
}

body {
	/* my custom properties */
	--accent-color: rgb(55, 0, 255);
	--light-color: 170, 170, 170;
	--light-alpha-color: 0;

	--bg-color: rgba(var(--light-color), var(--light-alpha-color));
	--modal-color: rgba(var(--light-color), 1);
	--line-color: rgba(20, 20, 20, 0.2);

	/* foundations */
	--border-width: 1px;

	--text-selection: color-mix(in srgb, var(--accent-color) 20%, transparent);
	--text-highlight-bg: color-mix(in srgb, var(--accent-color) 20%, transparent);

	--radius-s: 2px;
	--radius-m: 8px;
	--radius-l: 12px;
	--radius-xl: 16px;

	--input-radius: 0px;
	--tab-radius-active: 0px;
	
	--toggle-radius: 0px;
	--toggle-thumb-radius: 0px;
	--slider-thumb-radius: 0px;

	--font-interface-theme: 'Pretendard-Regular', serif;
	--font-text-theme: 'Noto Serif KR', serif;

	--bold-modifier: 500;
	--line-height-normal: 2em;

	/* components */
	--button-radius: var(--radius-s);

	--checkbox-radius: 0px;
	--checkbox-marker-color: rgb(101, 101, 101);
	--checkbox-color: rgba(152, 151, 151, 0.766);

	--modal-background: var(--modal-color);
	--modal-radius: var(--radius-l);

	--popover-width: 450px;
	--popover-height: 300px;
	--popover-font-size: 0.9em;

	/* editor */
	--blockquote-border-thickness: 3px;
	--blockquote-border-color: color-mix(in srgb, var(--accent-color) 60%, transparent);
	--blockquote-font-style: italic;

	--callout-border-width: 1px;
	--callout-border-opacity: 100%;
	--callout-padding: 15px 20px;
	--callout-radius: 20px;
	--callout-blend-mode: multiply;
	
	--code-normal: #333d40;
    --code-comment: #5b6a6a;
    --code-function: #b500e7;
    --code-important: #d64609;
    --code-keyword: #098800;
    --code-operator: #c45b00;
    --code-property: #333d40;
    --code-punctuation: #00b4f0;
    --code-string: #b58900;
    --code-tag: #dc322f;
    --code-value: var(--accent-color);
	
	--file-line-width: 630px;
	--file-folding-offset: 300px;
	--file-margins: 30px 10px;
	--file-header-border: 1px solid var(--line-color);
	--file-header-justify: center;

	--h1-font: 'Pretendard-Bold';
	--h2-font: 'Pretendard-Bold';
	--h3-font: 'Pretendard-Bold';
	--h4-font: 'Pretendard-Bold';
	--h5-font: 'Pretendard-Bold';
	--h6-font: 'Pretendard-Bold';
	--h1-size: 2em;
	--h2-size: 1.8em;
	--h3-size: 1.4em;
	--h4-size: 1.2em;
	--h5-size: 1.1em;
	--h6-size: 1em;
	--h1-weight: 700;
	--h2-weight: 700;
	--h3-weight: 700;
	--h4-weight: 700;
	--h5-weight: 700;
	--h6-weight: 700;

	--hr-color: var(--line-color);
	--hr-thickness: var(--border-width);

	--inline-title-size: 2.3em;
	--inline-title-font: "ITC Slimbach Std", 'Noto Serif KR' ;
	--inline-title-line-height: 1.2em;
	--inline-title-color: var(--color-base-100);
	--inline-title-size: 3.5em;

	--link-color: var(--accent-color);
	--link-unresolved-color: var(--accent-color);
	--link-unresolved-decoration-color: var(--accent-color);
	--link-external-color: var(--accent-color);

	--list-indent: 2em;
	--list-indent-editing: 2em;
	--list-indent-source: 2em;
	--list-spacing: 0px;
	--list-marker-color: var(--color-base-100);
	--list-marker-color-hover: var(--color-base-100);
	--list-marker-color-collapsed: var(--color-base-100);

	--metadata-background: rgba(20, 20, 20, 0.05);
	--metadata-max-width: 100%;
	--metadata-padding: 5px 20px;
	--metadata-border-radius: 10px;
	--metadata-gap: 0px;

	--table-column-first-border-width: 0;
	--table-column-last-border-width: 0;
	--table-header-border-width: 0;
	--table-last-border-width: 0;
	--table-row-last-border-width: 0;

	--tag-color: var(--accent-color);
	--tag-background:color-mix(in srgb, var(--accent-color) 20%, transparent);

	/* plugins */
	--graph-line: var(--line-color);

	/* window */
	--status-bar-background: var(--modal-background);
	--status-bar-border-color: var(--line-color);
	--status-bar-border-width: var(--border-width);
	--status-bar-radius: var(--radius-s);
}

.workspace-tab-header.is-active::before, .workspace-tab-header.is-active::after {
	display: none;
}

svg * {
	stroke-linecap: square;
	stroke-linejoin: miter;
}

.theme-light {
	--color-base-00: #f7f7f730; /*text input*/
	--color-base-05: #d5d0d034;
	--color-base-10: #f7f7f7c1; /*code background */
	--color-base-20: #d5d0d034;
	--color-base-25: #d5d0d034;
	--color-base-30: rgba(20, 19, 19, 0.172); /*grid line*/
	--color-base-35: #d5d0d034;
	--color-base-40: #d5d0d034;
	--color-base-50: rgb(20, 20, 20); /*top bar text*/
	--color-base-60: #d5d0d034;
	--color-base-100: rgb(20, 20, 20);
	
	--background-primary: linear-gradient(to left, #ffffff00 93%, var(--line-color));
	--background-secondary: linear-gradient(to left, var(--bg-color) 100%, var(--line-color));
}

u {
	text-decoration-thickness: 1px;
	text-underline-position : under;
	text-underline-offset : 1px;
}

a {
	text-decoration-thickness: 1px;
	text-underline-position : under;
	text-underline-offset : 1px;
}

del {
	text-decoration-thickness: 1px;
}

small {
	font-family: 'Pretendard-Regular';
	color: rgba(20, 20, 20, 0.4);
}

.inline-title {
	letter-spacing: 0em;
	word-break: keep-all;
}

.ͼ1 .cm-lineWrapping,  p {
	word-break: keep-all;
}

.math-block > mjx-container[jax="CHTML"]  {
    background-color:#f7f7f7c1;
	padding: 15px;
	font-size: 1.25em;
}

.callout[data-callout="callout"], .callout[data-callout="note"] {
	--callout-color: var(--accent-color);
}
.callout[data-callout="abstract"], .callout[data-callout="tip"] {
	--callout-color: rgb(0, 142, 123);
}
.callout[data-callout="success"]{
	--callout-color: rgb(0, 124, 37);
}
.callout[data-callout="question"], .callout[data-callout="warning"] {
	--callout-color: rgb(149, 92, 0);
}
.callout[data-callout="failure"], .callout[data-callout="danger"], .callout[data-callout="bug"] {
	--callout-color: rgb(149, 0, 0);
}

.popover {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: multiply;
}

.modal {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: multiply;
}

.suggestion-container.mod-search-suggestion {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: normal;
	border: var(--line-color);
	border-width: var(--border-width);
}

.graph-controls {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: soft-light;
}

.prompt {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: multiply;
}

.dialog {
	background-color: var(--modal-color);
	backdrop-filter: blur(5px);
	mix-blend-mode: multiply;
}

.cm-scroller, .markdown-reading-view {
	background: var(--background-primary);
}

.app-container {
	background: var(--background-secondary);
	mix-blend-mode: multiply;
}

.HyperMD-quote, blockquote {
	background: linear-gradient(to left, #ffffff00 70%, color-mix(in srgb, var(--accent-color) 20%, transparent));
}

iframe {
	width: 120%;
    left: -10%;
    position: absolute;
    height: 1500px;
}